const SHELF_CSS='<style id="shelf-css">'+
'.shelf-index{display:grid;grid-template-columns:repeat(auto-fill,minmax(210px,1fr));gap:10px;margin:0 0 34px}'+
'.shelf-index a{display:grid;grid-template-columns:auto 1fr;gap:2px 12px;align-items:start;text-decoration:none;background:var(--card);border:1px solid var(--line);border-top:3px solid var(--gold);border-radius:var(--r);padding:12px 14px;transition:transform .2s,border-color .2s,box-shadow .2s}'+
'.shelf-index a:hover{transform:translateY(-2px);border-color:var(--gold);box-shadow:0 8px 20px rgba(33,29,25,.08)}'+
'.shelf-index .n{grid-row:span 2;font-family:"Cormorant Garamond",serif;font-size:30px;line-height:1;color:var(--gold-deep)}'+
'.shelf-index b{font-size:14.5px;line-height:1.35;color:var(--ink)}.shelf-index em{font-style:normal;font-size:12.5px;color:var(--muted)}'+
'.shelf{margin:0 0 46px;scroll-margin-top:90px}'+
'.shelf-head{display:flex;gap:16px;align-items:flex-end;padding-bottom:12px;margin-bottom:20px;border-bottom:2px solid var(--ink);position:relative}'+
'.shelf-head::after{content:"";position:absolute;left:0;right:0;bottom:-8px;height:6px;background:linear-gradient(180deg,rgba(169,137,91,.28),transparent)}'+
'.shelf-head .n{font-family:"Cormorant Garamond",serif;font-size:clamp(40px,6vw,58px);line-height:.8;color:var(--gold)}'+
'.shelf-head h2{font-size:clamp(21px,2.6vw,27px);line-height:1.3}.shelf-head p{color:var(--ink-soft);font-size:14.5px;margin-top:2px}'+
'.shelf-head .cnt{margin-left:auto;white-space:nowrap;font-size:12.5px;letter-spacing:.06em;color:var(--gold-deep);border:1px solid var(--gold);border-radius:999px;padding:3px 10px}'+
'.shelf .card h3{font-size:16px}'+
'.shelf .card.is-new{position:relative}.shelf .card.is-new::after{content:attr(data-new);position:absolute;top:10px;left:10px;background:var(--ink);color:#fff;font-size:11.5px;letter-spacing:.08em;padding:3px 9px;border-radius:999px}'+
'.shelf-top{display:inline-block;margin-top:10px;font-size:13px;color:var(--gold-deep);text-decoration:none}'+
'@media (max-width:980px){.shelf .cards{display:flex;overflow-x:auto;scroll-snap-type:x mandatory;gap:14px;padding:2px 16px 12px;margin-inline:-16px;scrollbar-width:thin}'+
'.shelf .cards>.card{flex:0 0 44%;scroll-snap-align:start}.shelf-swipe{display:block}}'+
'.shelf-swipe{display:none;font-size:12.5px;color:var(--muted);margin:-10px 0 10px}'+
'@media (max-width:640px){.shelf-head{flex-wrap:wrap}.shelf-head .cnt{margin-left:0}.shelf .cards>.card{flex:0 0 80%}.shelf-index{grid-template-columns:1fr 1fr}.shelf-index a{padding:10px}.shelf-index .n{font-size:24px}}'+
'</style>';
function slugOf(a){const m=a.match(/href="[^"]*\/([^\/"]+)\/"/);return m?m[1]:'';}
function shelfify(t,cat,en,extra){
 const S=SHELVES[cat];if(!S)return t;
 const i=t.indexOf('<div class="cards');if(i<0)return t;
 const mEnd=t.indexOf('</main>',i);const seg=t.slice(i,mEnd);const la=seg.lastIndexOf('</article>');if(la<0)return t;
 const close=t.indexOf('</div>',i+la)+6;
 const arts=t.slice(i,close).match(/<article class="card">[\s\S]*?<\/article>/g)||[];
 const by={};const order=[];
 for(const a of arts){const s=slugOf(a);if(s&&!by[s]){by[s]=a;order.push(s);}}
 for(const x of (extra||[])){if(!by[x.slug]){by[x.slug]=x.html;order.unshift(x.slug);}}
 const used=new Set();const shelves=[];
 for(const sh of S){const items=sh.s.filter(s=>by[s]);items.forEach(s=>used.add(s));if(items.length)shelves.push({t:en?sh.en:sh.th,items});}
 const rest=order.filter(s=>!used.has(s));
 if(rest.length)shelves.push({t:en?["More articles","Other articles in this category"]:["บทความอื่น ๆ","บทความเพิ่มเติมในหมวดนี้"],items:rest});
 const unit=en?' articles':' บทความ';
 const pad=n=>String(n).padStart(2,'0');
 let idx='<nav class="shelf-index" id="shelf-index" aria-label="'+(en?'Topics in this category':'หัวข้อในหมวดนี้')+'">';
 let body='';
 shelves.forEach((sh,k)=>{const id='shelf-'+(k+1);
  idx+='<a href="#'+id+'"><span class="n">'+pad(k+1)+'</span><b>'+sh.t[0]+'</b><em>'+sh.items.length+unit+'</em></a>';
  body+='<section class="shelf" id="'+id+'" aria-labelledby="'+id+'-h"><header class="shelf-head"><span class="n">'+pad(k+1)+'</span><div><h2 id="'+id+'-h">'+sh.t[0]+'</h2><p>'+sh.t[1]+'</p></div><span class="cnt">'+sh.items.length+unit+'</span></header>'+(sh.items.length>1?'<p class="shelf-swipe">'+(en?'Swipe for more →':'ปัดเพื่อดูเพิ่ม →')+'</p>':'')+'<div class="cards cards-3">'+sh.items.map(s=>by[s]).join('')+'</div><a class="shelf-top" href="#shelf-index">'+(en?'↑ All topics':'↑ ดูหัวข้อทั้งหมด')+'</a></section>';});
 idx+='</nav>';
 let out=t.slice(0,i)+idx+body+t.slice(close);
 const total=order.length;
 out=out.replace(/(<header class="cat-head">[\s\S]*?<p class="small">)[^<]*(<\/p>)/,'$1'+total+unit+' · '+shelves.length+(en?' topics':' หมวดย่อย')+'$2');
 out=out.replace('</head>',SHELF_CSS+'</head>');
 return out;
}

